24	interface Item {
25	  type: string;
26	  material?: string;
27	  enchantment?: number;
28	  cursed?: boolean;
29	}
30	
31	const HIGH_ENCHANTMENT_THRESHOLD = 5;
32	
33	const isCursed = (item: Item): boolean => item.cursed === true;
34	const isHighlyEnchanted = (item: Item): boolean =>
35	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
36	
37	const SURCHARGE_RATES: ReadonlyArray<{ applies: (item: Item) => boolean; rate: number }> = [
38	  { applies: isCursed, rate: 0.5 },
39	  { applies: isHighlyEnchanted, rate: 0.3 },
40	];
41	
42	const itemSurcharge = (item: Item): number => {
43	  const base = BASE_PREMIUM[item.type] ?? 0;
44	  const totalRate = SURCHARGE_RATES
45	    .filter(({ applies }) => applies(item))
46	    .reduce((sum, { rate }) => sum + rate, 0);
47	  return base * totalRate;
48	};
49	
50	const itemsSurcharge = (items: Item[]): number =>
51	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
52	
53	interface QuoteStep {
54	  op: "quote";
55	  items: Item[];
56	}
57	
58	interface Damage {
59	  itemType: string;
60	  amount: number;
61	}
62	
63	interface ClaimStep {
64	  op: "claim";
65	  policy: number;
66	  incident: {
67	    cause: string;
68	    damages: Damage[];
69	  };
70	}
71	
72	type Step = QuoteStep | ClaimStep;
73	
74	interface Customer {
75	  yearsWithMHPCO: number;
76	}
77	
78	interface Scenario {
79	  customer: Customer;
80	  steps: Step[];
81	}
82	
83	interface QuoteResult {
84	  premium: number;
85	}
86	
87	interface ClaimResult {
88	  payout: number;
89	  remainingCap: number;
90	}
91	
92	type StepResult = QuoteResult | ClaimResult;
93	
94	interface ScenarioResult {
95	  results: StepResult[];
96	}
97	
98	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
99	const COMPONENT_BLOCK_SIZE = 3;
100	const COMPONENT_BLOCK_BASE = 60;
101	
102	const roundUpInMHPCOsFavor = (amount: number): number => Math.ceil(amount);
103	const roundDownInMHPCOsFavor = (amount: number): number => Math.floor(amount);
104	
105	const groupCountsByType = (items: Item[]): Map<string, number> => {
106	  const counts = new Map<string, number>();
107	  for (const item of items) {
108	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
109	  }
110	  return counts;
111	};
112	
113	const typeBasePremium = (type: string, count: number): number => {
114	  if (COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE) {
115	    return COMPONENT_BLOCK_BASE;
116	  }
117	  return BASE_PREMIUM[type] * count;
118	};
119	
120	const itemsBasePremium = (items: Item[]): number =>
121	  [...groupCountsByType(items)].reduce(
122	    (total, [type, count]) => total + typeBasePremium(type, count),
123	    0,
124	  );
125	
126	const firstInsuranceSurcharge = (base: number): number => base * FIRST_INSURANCE_RATE;
127	
128	const LOYALTY_YEARS_THRESHOLD = 2;
129	const LOYALTY_DISCOUNT_RATE = 0.2;
130	
131	const isLoyalCustomer = (customer: Customer): boolean =>
132	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
133	
134	const loyaltyDiscount = (customer: Customer, base: number): number =>
135	  isLoyalCustomer(customer) ? base * LOYALTY_DISCOUNT_RATE : 0;
136	
137	const quotePremium = ({ items }: QuoteStep, customer: Customer): number => {
138	  const base = itemsBasePremium(items);
139	  const premiumBeforeFee =
140	    base + itemsSurcharge(items) + firstInsuranceSurcharge(base) - loyaltyDiscount(customer, base);
141	  return roundUpInMHPCOsFavor(premiumBeforeFee + PROCESSING_FEE);
142	};
143	
144	interface Policy {
145	  remainingCap: number;
146	}
147	
148	const itemInsuranceValue = (item: Item): number => INSURANCE_VALUE[item.type] ?? 0;
149	
150	const createPolicy = (step: QuoteStep): Policy => {
151	  const insuranceSum = step.items.reduce((sum, item) => sum + itemInsuranceValue(item), 0);
152	  return { remainingCap: insuranceSum * CAP_MULTIPLIER };
153	};
154	
155	const damagePayout = (damage: Damage): number =>
156	  Math.max(0, damage.amount - DEDUCTIBLE);
157	
158	const processClaim = (step: ClaimStep, policies: Map<number, Policy>): ClaimResult => {
159	  const policy = policies.get(step.policy)!;
160	  const rawPayout = step.incident.damages.reduce((sum, d) => sum + damagePayout(d), 0);
161	  const payout = roundDownInMHPCOsFavor(Math.min(rawPayout, policy.remainingCap));
162	  policy.remainingCap -= payout;
163	  return { payout, remainingCap: policy.remainingCap };
164	};
165	
166	export const runScenario = (scenario: Scenario): ScenarioResult => {
167	  const policies = new Map<number, Policy>();
168	  const results: StepResult[] = scenario.steps.map((step, index) => {
169	    if (step.op === "quote") {
170	      policies.set(index, createPolicy(step));
171	      return { premium: quotePremium(step, scenario.customer) };
172	    }
173	    return processClaim(step, policies);
174	  });
175	  return { results };
176	};
